package io.github.dirtyredz.roundwood.client.material;

import io.github.dirtyredz.roundwood.Roundwood;
import io.github.dirtyredz.roundwood.appearance.material.MasonryMaterials;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.DyeColor;

/**
 * Artwork bindings for paint and masonry, all generated by {@code tools/generate-textures.mjs}:
 * every dye has opaque painted full-height door boards ({@code door_panel_<dye>}, also the painted
 * trim face) and painted window boards ({@code panel_<dye>}); each supported masonry material has
 * its radial face and granular edge. Paint is its own artwork, never a multiplied donor colour.
 */
public final class PaintStyles {
    private PaintStyles() {
    }

    public static ResourceLocation doorPanel(DyeColor dye) {
        return texture("door_panel_" + dye.getName());
    }

    public static ResourceLocation windowPanel(DyeColor dye) {
        return texture("panel_" + dye.getName());
    }

    public static ResourceLocation masonryFace(MasonryMaterials.Material material) {
        return texture("trim_radial_" + material.artwork());
    }

    public static ResourceLocation masonryEdge(MasonryMaterials.Material material) {
        return texture("trim_edge_" + material.artwork());
    }

    private static ResourceLocation texture(String name) {
        return ResourceLocation.fromNamespaceAndPath(Roundwood.MOD_ID, "block/" + name);
    }
}
